INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('7a7f2344-31bc-55ec-a9d3-ca66ca6b99fd', 'b19b1d6f-7459-5798-8f84-2dbac1a6f893', 'en', $h$Mechanical Rotary Gear Oil Pump 18 L – 4018$h$, $h$mechanical-rotary-gear-oil-pump-18-l-4018$h$, NULL, $h$<div> <div><p><strong>Why the 4018 Mechanical Rotary Gear Oil Pump?</strong></p><p>The mechanical rotary gear oil pump has an 18 L capacity. It is used for topping up transmission and differential oils. The rotary transmission oil pump uses a ½ ” fabric-reinforced hose. It has two wheels and, being lightweight, can be moved around easily; in addition, the foot pedal keeps the oil dispenser steady during operation. It offers great convenience in facilities without a compressed air system.</p></div> </div>$h$, NULL, $h$Mechanical Rotary Gear Oil Pump 18 L – 4018 | HD Marine$h$, $h$Why the 4018 Mechanical Rotary Gear Oil Pump? The mechanical rotary gear oil pump has an 18 L capacity. It is used for topping up transmission and…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('82e6a596-f610-5285-8bff-b436e6ea2d83', 'b4d33a2b-dc7e-55ab-b12c-af0c192c4b82', 'en', $h$Pneumatic Oil Extraction Pumps$h$, $h$pneumatic-oil-extraction-pumps$h$, $h$Aro® Compatible Spare Parts$h$, $h$<div> <div><p>Aro® first introduced its air-operated double diaphragm pump in the 1980s in Bryan, Ohio (United States). Today, ARO® is part of Ingersoll Rand Corp. and one of the leading AODD Pump brands.</p></div> </div><div> <div><p>ARO® air-operated diaphragm pumps have the capacity to transfer a wide range of viscous fluids and provide stall-free, ice-free operation. The unbalanced air valve design prevents the stalling problems associated with other pumps. Quick-dump exhaust valves direct cold exhaust air away from ice-prone components and prevent freezing. Depending on the type of fluid to be transferred, piston pump packages are available in multiple configurations, including single-body, two-body and heavy-duty two-body versions.</p><p>ARO® diaphragm pumps are a good choice for industrial and chemical applications thanks to their cost-effectiveness and reliable construction. The bolted, leak-free design eliminates cross-contamination and increases operator safety. Their modular structure, reduced part count and easy-to-use repair kits also minimize repair time when service is required.</p><p>HD Marine brings you reliable, high-quality spare parts compatible with double diaphragm (AODD) pumps. In addition to providing replacement support for many parts of your choice, HD Marine is the place to find Aro spare parts such as<strong> valve balls, valve seats, diaphragms, gaskets, clamp bands, mufflers, pistons and valve rings</strong>.</p><p>In the event of any failure or maintenance on diaphragm pumps, you can select individual Aro-compatible products on the HD Marine website, or visit the <strong>Aro Service Kits</strong> section to access service/repair kits that combine screws, gaskets and a wide variety of rings. Service kits come in two types: a wet-end kit for the wet section of your pneumatic double diaphragm pump, and a kit used for the maintenance and repair of the air side of your air-operated double diaphragm pump. Since these two kits contain different products, you should make your choice by considering which products you need and where you will use them.</p><p>If you prefer to purchase items individually rather than <strong>Aro Service Kits</strong>, you can also browse <strong>Aro gaskets, Aro rings, Aro valve balls, Aro valve seats, Aro hardware and Aro diaphragms</strong>. However, keep in mind that the application area in which each industry uses its pumps — and the appropriate Aro spare part for that area — will vary. To match your specific application needs such as chemical compatibility, temperature and sealing capacity, HD Marine offers its customers the most widely used and preferred quality materials and products for pump parts, such as <strong>Santoprene, Hytrel, N-fit, PTFE and Neoprene</strong>.</p></div> </div>$h$, NULL, $h$Pneumatic Oil Extraction Pumps | HD Marine$h$, $h$Aro® first introduced its air-operated double diaphragm pump in the 1980s in Bryan, Ohio (United States). Today, ARO® is part of Ingersoll Rand Corp. and…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('70b3d0bf-f603-5fb9-ab41-9943b4f623c2', '959ca29a-330d-568f-8e2e-c4debb91bac8', 'en', $h$Drum Faucet – 44387$h$, $h$drum-faucet-44387$h$, NULL, $h$<div> <div><p><strong>Why the 44387 Drum Faucet?</strong></p><p>Drum faucets are an excellent solution for conveniently dispensing fluid from 210-liter drums. It is made of polyethylene. These faucets allow fluids to be dispensed easily under gravity flow when the drum is positioned horizontally.</p></div> </div>$h$, NULL, $h$Drum Faucet – 44387 | HD Marine$h$, $h$Why the 44387 Drum Faucet? Drum faucets are an excellent solution for conveniently dispensing fluid from 210-liter drums. It is made of polyethylene…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('d734ae08-0be3-524e-95e2-cda813809605', 'af3d5de4-fa76-5103-ae94-2e1cb482653c', 'en', $h$Oil Spill Containment Basin 125 L – YTK2$h$, $h$oil-spill-containment-basin-125-l-ytk2$h$, NULL, $h$<div> <div><p><strong>Why the YTK2 Oil Spill Containment Basin?</strong></p><p>In accordance with occupational safety and environmental waste regulations, leak- and overflow-preventing containment basins must be used when emptying or filling chemicals and hazardous waste.</p><p>For 2 drums of 208 liters each;<br/>Durable and long-lasting thanks to edge profiles on both sides. Easy and safe handling with forklifts, stackers and pallet trucks.</p></div> </div>$h$, NULL, $h$Oil Spill Containment Basin 125 L – YTK2 | HD Marine$h$, $h$Why the YTK2 Oil Spill Containment Basin? In accordance with occupational safety and environmental waste regulations, leak- and overflow-preventing…$h$, 'auto') ON CONFLICT DO NOTHING;
