INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('87511a17-69d3-51ba-b4fd-d7f78dbc9bb1', 'aedf37c8-e08f-5115-9ac0-0d18df9bb4f3', 'en', $h$Parts Washing Machine 80 L – 9200$h$, $h$parts-washing-machine-80-l-9200$h$, NULL, $h$<div> <div><p><strong>Why the 9200 Parts Washing Machine?</strong></p><p>The air-operated parts washing unit is ideal for cleaning small disassembled engine components of vehicles and machinery, vehicle parts and machine tool parts. The cleaning basin holds 45 L and the tank capacity is 80 L. With two fixed and two swivel wheels, its mobility is excellent. The unit is very simple to use, and a water-based solvent must be used. The tank is drained with air, and the safety relief valve on the tank provides protection against excessive air pressure. This air-operated machine can be used for a limited time without a continuous air connection, as well as with the immersion method. A brush is provided for washing and an air gun for quick drying. The fluid level in the tank is monitored on the tank scale. A drain plug is provided for removing solid residues that accumulate inside the tank. It must never be used with corrosive, flammable, explosive or combustible fluids.</p></div> </div>$h$, NULL, $h$Parts Washing Machine 80 L – 9200 | HD Marine$h$, $h$Why the 9200 Parts Washing Machine? The air-operated parts washing unit is ideal for cleaning small disassembled engine components of vehicles and…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('cee9cff9-df2a-5a69-ad76-933fd93bd429', 'd4393ec7-cd46-5bdc-8d41-5fed4106f2cf', 'en', $h$Mobile Grease Drum System – SVS2400$h$, $h$mobile-grease-drum-system-svs2400$h$, NULL, $h$<div> <div><p><strong>Why the SVS2400 Mobile Grease Drum System?</strong></p><p>The mobile grease lubrication trolley is available in many versions for different purposes. Pump options with different output and pressure ratios, hose lengths of up to 20 meters, and gram-totalizing metered guns that can be adapted to the system on request give it a very high working capability. Considering the differing needs of every business, these systems offer an excellent solution. The drum trolley is manufactured from quality sheet steel and finished with electrostatic paint; with two swivel and two fixed wheels, it is highly maneuverable. The SVS2400 grease drum system consists of 8 standard components, but you can choose your own grease pump, grease gun and grease hose length.</p></div> </div>$h$, NULL, $h$Mobile Grease Drum System – SVS2400 | HD Marine$h$, $h$Why the SVS2400 Mobile Grease Drum System? The mobile grease lubrication trolley is available in many versions for different purposes. Pump options with…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('d2d331e0-d9a3-5c47-9557-0082181ef367', '10ff28c8-92bb-585f-a529-089dccd83e3b', 'en', $h$Mobile Oil Drum System with Hose Reel – SVS4500$h$, $h$mobile-oil-drum-system-with-hose-reel-svs4500$h$, NULL, $h$<div> <div><p><strong>Why the SVS4500 Mobile Oil Drum System with Hose Reel?</strong></p><p>Offered in many versions for different purposes, the mobile oil dispensing trolley delivers very high working capability thanks to pump options with different output and pressure ratios, 10, 15 and 20-meter oil hose reels, and liter-metered guns you can add according to your needs. Taking the different needs of every business into account, we offer you an excellent solution. The drum trolley, which we manufacture from quality sheet steel and finish with electrostatic paint, is highly maneuverable thanks to its two swivel and two fixed wheels. The SVS4500 oil drum system consists of four standard components; however, you can build different sets by choosing your own oil pump, oil gun and oil hose reel.</p><div> </div></div> </div>$h$, NULL, $h$Mobile Oil Drum System with Hose Reel – SVS4500 | HD Marine$h$, $h$Why the SVS4500 Mobile Oil Drum System with Hose Reel? Offered in many versions for different purposes, the mobile oil dispensing trolley delivers very…$h$, 'auto') ON CONFLICT DO NOTHING;
