INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('ce83ed8a-dfa6-5ed2-abb7-e8eb1e815b9c', 'e5466a2e-e2cf-5671-a74b-95b235ea71a2', 'en', $h$Mechanical Metered Oil Gun – 4109$h$, $h$mechanical-metered-oil-gun-4109$h$, NULL, $h$<div> <div><p><strong>Why the 4109 Mechanical Metered Oil Gun?</strong></p><p>The mechanical liter-metered oil gun lets you control the dispensed oil volume even under the most demanding conditions. No calibration is required. It keeps a simple, easy-to-read, fully mechanical record. It features a five-digit totalizer display.</p><p> </p></div> </div>$h$, NULL, $h$Mechanical Metered Oil Gun – 4109 | HD Marine$h$, $h$Why the 4109 Mechanical Metered Oil Gun? The mechanical liter-metered oil gun lets you control the dispensed oil volume even under the most demanding…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('99c4e10c-2223-50ea-82ce-cd975b9b91d8', 'acb4b335-674a-5524-af41-86734c0a466a', 'en', $h$Heavy-Duty Metered Oil Gun – 4108$h$, $h$heavy-duty-metered-oil-gun-4108$h$, NULL, $h$<div> <div><h4><strong>Why the 4108 Heavy-Duty Metered Oil Gun?</strong></h4><p>Ideal for users seeking high efficiency and time savings. A digital flow meter for all types of synthetic and mineral oils, a battery-powered digital display, and the ability to view both the oil volume of each dispense and the total volume; the metering unit delivers highly accurate results regardless of oil viscosity, ambient temperature or system pressure. The polycarbonate housing is extremely durable, and the device is long-lasting even under harsh working conditions. Its ergonomic design provides comfortable use.</p></div> </div>$h$, NULL, $h$Heavy-Duty Metered Oil Gun – 4108 | HD Marine$h$, $h$Why the 4108 Heavy-Duty Metered Oil Gun? Ideal for users seeking high efficiency and time savings. A digital flow meter for all types of synthetic and…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('0e7b22c7-8b85-51c5-8c8d-abd5c35b1e48', '0ab40a85-1dfb-5e61-82b4-3d71aa8c755a', 'en', $h$Preset Metered Oil Gun – 4107$h$, $h$preset-metered-oil-gun-4107$h$, NULL, $h$<div> <div><p><strong>Why the 4107 Preset Metered Oil Gun?</strong></p><p>Without liter-metered guns, there is no way to measure oil volume accurately while avoiding environmental pollution and occupational safety risks. In every situation where you want to accurately determine the amount of fluid transferred or calculate the correct amount of oil to add to an engine, liter-metered guns offer you durability, ease of use and high reliability. On model 4107, once the preselected amount has been dispensed, the gun shuts off automatically and stops dispensing.</p></div> </div>$h$, NULL, $h$Preset Metered Oil Gun – 4107 | HD Marine$h$, $h$Why the 4107 Preset Metered Oil Gun? Without liter-metered guns, there is no way to measure oil volume accurately while avoiding environmental pollution…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('6b8daad9-94e4-5cce-a204-22afde8016bd', '22127a0f-e5f5-52d7-a9d9-bc72243eb366', 'en', $h$Metered Oil Gun – 4106S$h$, $h$metered-oil-gun-4106s$h$, NULL, $h$<div> <div><p><strong>Why the 4106S Metered Oil Gun?</strong></p><p>The 4106S electronic metered oil gun, produced for oil, has an oval gear design and is a manageable, ergonomic tool for controlling and managing oil dispensing. The meter body is made of die-cast aluminum resistant to high pressures. It is easy to calibrate and features an electronic reset function. In addition to low battery consumption, it carries an IP65 protection rating.</p></div> </div>$h$, NULL, $h$Metered Oil Gun – 4106S | HD Marine$h$, $h$Why the 4106S Metered Oil Gun? The 4106S electronic metered oil gun, produced for oil, has an oval gear design and is a manageable, ergonomic tool for…$h$, 'auto') ON CONFLICT DO NOTHING;
